
(function(root){const P=root.NeonAudio.CombatAudio.prototype;
P.camera128=function(variation=0){const c=this.context();if(!c)return;const t=c.currentTime;for(const [delay,duration,volume]of [[0,.018,.038],[.032,.025,.019]]){const n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=this.noise(c);f.type='highpass';f.frequency.value=1800+variation*230;g.gain.setValueAtTime(volume,t+delay);g.gain.exponentialRampToValueAtTime(.0001,t+delay+duration);n.connect(f).connect(g).connect(c.destination);n.start(t+delay,.1+variation*.17);n.stop(t+delay+duration);}};
P.novaAir128=function(down=false){const c=this.context();if(!c)return;const t=c.currentTime,n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=this.noise(c);f.type='bandpass';f.Q.value=.8;f.frequency.setValueAtTime(down?1500:300,t);f.frequency.exponentialRampToValueAtTime(down?260:1600,t+.2);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.045,t+.05);g.gain.exponentialRampToValueAtTime(.001,t+.24);n.connect(f).connect(g).connect(c.destination);n.start(t,.6);n.stop(t+.25);};
P.stopCrowd128=function(fade=.12){const q=this.crowdState128;if(!q)return;this.crowdState128=null;const t=q.context.currentTime;q.gain.gain.cancelScheduledValues(t);q.gain.gain.setTargetAtTime(.0001,t,Math.max(.01,fade/3));let left=q.sources.length;for(const n of q.sources){n.onended=()=>{if(--left===0)q.gain.disconnect();};try{n.stop(t+fade);}catch{if(--left===0)q.gain.disconnect();}}};
P.syncCrowd128=function(action,enabled=true){const frame=action?.t*60;if(!enabled||!action?.exploding128||action.cleaned128||frame<9){this.stopCrowd128();return;}const c=this.context();if(!c){this.stopCrowd128();return;}let q=this.crowdState128;if(q&&q.id!==action.id128){this.stopCrowd128();q=null;}if(!q){const gain=c.createGain(),sources=[];gain.gain.setValueAtTime(.001,c.currentTime);gain.connect(c.destination);const n=c.createBufferSource(),f=c.createBiquadFilter();n.buffer=this.noise(c);n.loop=true;f.type='bandpass';f.frequency.value=760;f.Q.value=.55;n.connect(f).connect(gain);n.start();sources.push(n);for(let i=0;i<5;i++){const o=c.createOscillator(),form=c.createBiquadFilter(),voice=c.createGain(),vib=c.createOscillator(),vg=c.createGain();o.type='sawtooth';o.frequency.value=175+i*43;vib.frequency.value=3.5+i*.45;vg.gain.value=8+i;vib.connect(vg).connect(o.frequency);form.type='bandpass';form.frequency.value=650+i*170;form.Q.value=3;voice.gain.value=.075;o.connect(form).connect(voice).connect(gain);o.start();vib.start();sources.push(o,vib);}q=this.crowdState128={id:action.id128,context:c,gain,sources,level:-1};}const level=action.freezeLeft128>0?.12:frame>=116?.23:frame>=106?.85:frame>=59?.70:frame>=47?.55:.32;if(q.level!==level){q.level=level;q.gain.gain.cancelScheduledValues(c.currentTime);q.gain.gain.setTargetAtTime(level*.06,c.currentTime,frame>=116?.12:.04);}};
})(window);
